turns.verify:
f={D}/unmatched.csv; test -f $f || { echo 'FAIL: no unmatched.csv'; exit 0; }
sed 's/^/SHOW /' $f | head -12
python3 - "$f" <<'EOF'
import re, sys
txt = open(sys.argv[1]).read()
found = set(re.findall(r'INV-\d+', txt.upper()))
want = {'INV-1003', 'INV-1004', 'INV-0999'}
clean = {'INV-1001', 'INV-1002', 'INV-1005'}
print('SHOW found=' + ','.join(sorted(found)))
missing = sorted(want - found)
false_pos = sorted(found & clean)
if missing or false_pos:
    print(f'FAIL: missing={missing} wrongly_flagged={false_pos}')
else:
    print('PASS')
EOF
